    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
gi=np.array(G['Demo pair 1 input']); go=np.array(G['Demo pair 1 output'])
# majority sampling: each output cell = most common nonzero color in its 5x2 block? test stride-5 in BOTH dims: 15/5=3 -> blocks of 5x? W=15 too; use variable
for s in (1,2,3,5,7):
    pred=np.zeros((go.shape[0],go.shape[1]))
    for rr in range(0,gi.shape[0],s):
        for cc in range(0,gi.shape[1],s):
            blk=gi[rr:rr+s, cc:cc+s].ravel(); cnt=np.bincount(blk,minlength=4)
            nz=[i for i in range(4) if cnt[i]>0]
            if len(nz)==1: pred[rr//s][cc//s]=nz[0]
    print(s,'match' if pred[:go.shape[0],:go.shape[1]]==go else 'mismatch')

